/*
  n8n Code node
  Purpose: Recursively search every input item for a property named "articles"
           (case-insensitive) whose value is an array, then merge them.
           Then, filter articles within the last N hours and return the latest max_feed articles by publishedAt.
*/

const combinedArticles = [];

/**
 * Recursively traverse an object/array to collect every "articles" array.
 * @param {any} node - current node to inspect
 */
function collectArticles(node) {
  if (Array.isArray(node)) {
    node.forEach(collectArticles);
    return;
  }

  if (node && typeof node === 'object') {
    for (const [key, value] of Object.entries(node)) {
      if (key.toLowerCase() === 'articles' && Array.isArray(value)) {
        combinedArticles.push(...value);
      } else if (typeof value === 'object' && value !== null) {
        collectArticles(value);
      }
    }
  }
}

// Obtain all incoming items from all input branches
const allItems = $input.all();
for (const item of allItems) {
  collectArticles(item.json);
}

// Filter and sort articles
const latestArticles = combinedArticles
  .filter(article => {
    // Ensure publishedAt exists
    if (!article.publishedAt) {
      return false;
    }

    // Filter articles within the last N hours
    const articleDate = new Date(article.publishedAt);

    // Check if the article date is valid before comparing
    if (isNaN(articleDate.getTime())) {
      return false;
    }

    return true;
  });

// Output
return [{
  json: {
    articles: latestArticles,
    status: 'ok',
    totalResults: latestArticles.length,
  }
}];

