// Get the articles from the first input branch
const allArticles = $input.item.json.articles || [];

const seen = new Set();          // ❶ store normalized URLs
const uniqueArticles = [];       // ❷ keep only first article per URL

for (const art of allArticles) {
  const hash = art.url_hash;
  if (!hash) continue;         // skip if url missing

  // If we've never seen this URL, keep the article
  if (!seen.has(hash)) {
    seen.add(hash);
    uniqueArticles.push(art);
  }
}

// ❸ Now map over the unique list
return uniqueArticles.map(article => {
  const truncate = (str) => (str && str.length > 1000 ? str.slice(0, 1000) : str);
  const trim     = (str) => (typeof str === 'string' ? str.trim() : str);

  return {
    json: {
      url: trim(article.url),
      title: trim(truncate(article.title)),
      description: trim(truncate(article.description)),
      author: trim(article.author),
      publishedAt: article.publishedAt,
      urlToImage: article.urlToImage,
      source: article.source?.name,
      url_hash: article.url_hash,
      cookie: article.cookie
    }
  };
});

// Transform FoxNews RSS items to NewsAPI format
const transformedArticles = [];

for (const item of $input.all()) {
  const transformedArticle = {
    source: {
      id: "RSS",
      name: "RSS"
    },
    author: null,
    title: item.json.title,
    description: item.json.description || item.json.contentSnippet,
    url: item.json.link,
    urlToImage: null,
    publishedAt: item.json.pubDate,
    cookie: item.json.cookie,    
  };

  transformedArticles.push(transformedArticle);
}

// Return in NewsAPI format
return [{
  json: {
    status: "ok",
    totalResults: transformedArticles.length,
    articles: transformedArticles
  }
}];

/*
  n8n Code node
  Purpose: Filter RSS feed items by datetime (UTC)
           Apply time filtering based on filter_feed_hours
*/

// Get configuration values from global_config node
const filter_feed_hours = $('start_read_rss').first().json.filter_feed_hours;

// Calculate the UTC cutoff time (filter_feed_hours hours ago)
const now = new Date();
const cutoffTimeUTC = new Date(
  Date.UTC(
    now.getUTCFullYear(),
    now.getUTCMonth(),
    now.getUTCDate(),
    now.getUTCHours() - filter_feed_hours,
    now.getUTCMinutes(),
    now.getUTCSeconds(),
    now.getUTCMilliseconds()
  )
);

// Get all input items from RSS Read
const allItems = $input.all();

// Filter and sort RSS items (all in UTC)
const filteredItems = allItems
  .filter(item => {
    // Ensure pubDate exists
    if (!item.json.pubDate) {
      return false;
    }
    // Parse pubDate as UTC
    const itemDate = new Date(item.json.pubDate);
    if (isNaN(itemDate.getTime())) {
      return false;
    }
    // Compare using UTC time
    return itemDate.getTime() >= cutoffTimeUTC.getTime();
  })
  .sort((a, b) => {
    // Sort by pubDate in UTC
    const dateA = new Date(a.json.pubDate);
    const dateB = new Date(b.json.pubDate);
    return dateB.getTime() - dateA.getTime();
  })
  .map(item => {
    // Convert pubDate to a unified UTC ISO string for consistency
    const itemDate = new Date(item.json.pubDate);
    item.json.pubDate = itemDate.toISOString();
    return item;
  });

// Return the filtered items
return filteredItems;

/*
  n8n Code node
  Purpose: Recursively search every input item for a property named "articles"
           (case-insensitive) whose value is an array, then merge them.
           Then, filter articles within the last N hours (UTC) and return the latest max_feed articles by publishedAt (UTC).
*/

const combinedArticles = [];

/**
 * Recursively traverse an object/array to collect every "articles" array.
 * @param {any} node - current node to inspect
 */
function collectArticles(node) {
  if (Array.isArray(node)) {
    node.forEach(collectArticles);
    return;
  }

  if (node && typeof node === 'object') {
    for (const [key, value] of Object.entries(node)) {
      if (key.toLowerCase() === 'articles' && Array.isArray(value)) {
        combinedArticles.push(...value);
      } else if (typeof value === 'object' && value !== null) {
        collectArticles(value);
      }
    }
  }
}

// Get configuration values
const max_feed = $node["start_read_rss"].json["max_feed_items"];
const filter_feed_hours = $node["start_read_rss"].json["filter_feed_hours"];

// Calculate the UTC cutoff time (N hours ago)
const now = new Date();
const cutoffTimeUTC = new Date(
  Date.UTC(
    now.getUTCFullYear(),
    now.getUTCMonth(),
    now.getUTCDate(),
    now.getUTCHours() - filter_feed_hours,
    now.getUTCMinutes(),
    now.getUTCSeconds(),
    now.getUTCMilliseconds()
  )
);

// Obtain all incoming items from all input branches
const allItems = $input.all();
for (const item of allItems) {
  collectArticles(item.json);
}

// Filter and sort articles (all in UTC)
const latestArticles = combinedArticles
  .filter(article => {
    // Ensure publishedAt exists
    if (!article.publishedAt) {
      return false;
    }
    // Parse publishedAt as UTC
    const articleDate = new Date(article.publishedAt);
    if (isNaN(articleDate.getTime())) {
      return false;
    }
    // Compare using UTC time
    return articleDate.getTime() >= cutoffTimeUTC.getTime();
  })
  .sort((a, b) => {
    // Sort by publishedAt in UTC
    const dateA = new Date(a.publishedAt);
    const dateB = new Date(b.publishedAt);
    return dateB.getTime() - dateA.getTime();
  })
  .slice(0, max_feed);

// Output
return [{
  json: {
    articles: latestArticles,
    status: 'ok',
    totalResults: latestArticles.length,
  }
}];

const crypto = require('crypto');

const items = $input.all();

for (const item of items) {
  if (item.json.articles && Array.isArray(item.json.articles)) {
    for (const article of item.json.articles) {
        // normalize URL (strip query params like before)
        const cleanUrl = article.url.split('?')[0];

        // stronger + longer hash (but same variable name)
        article.url_hash = crypto.createHash('sha256')
          .update(cleanUrl)
          .digest('hex')
          .slice(0, 16); // was 8, now 16
    }
  }
}

return items;
